class Solution {public:
string generateString(string str1,string str2){int n=str1.size(),m=str2.size(),L=n+m-1;string ans(L,'a');vector<int> fixed(L);for(int i=0;i<n;i++)if(str1[i]=='T')for(int j=0;j<m;j++){int p=i+j;if(fixed[p]&&ans[p]!=str2[j])return "";ans[p]=str2[j];fixed[p]=1;}for(int i=0;i<n;i++)if(str1[i]=='F'){bool equal=true;for(int j=0;j<m;j++)if(ans[i+j]!=str2[j]){equal=false;break;}if(equal){int pos=-1;for(int j=m-1;j>=0;j--)if(!fixed[i+j]&&str2[j]=='a'){pos=i+j;break;}if(pos<0)return "";ans[pos]='b';}}for(int i=0;i<n;i++){bool equal=true;for(int j=0;j<m;j++)if(ans[i+j]!=str2[j]){equal=false;break;}if(equal!=(str1[i]=='T'))return "";}return ans;}
};
